BEGIN TRANSACTION;

-- SQL statement 001710 via duckdb_extract_statements
SELECT value FROM egglog_backend_counters WHERE name = 'generation';

-- SQL statement 001711 via duckdb_extract_statements
SELECT value FROM egglog_backend_counters WHERE name = 'fresh_id';

-- SQL statement 001712 via duckdb_extract_statements
CREATE TEMP TABLE egglog_path_stage_3_0 AS
             WITH bindings AS (
                 SELECT DISTINCT
                        first.c0 AS c0,
                        first.c1 AS c1,
                        first.c2 AS c2,
                        second.c1 AS c3,
                        second.c2 AS c4
                 FROM egglog_function_22 AS first
                 JOIN egglog_function_22 AS second
                   ON first.c1 IS NOT DISTINCT FROM second.c0
                 WHERE first.__subsumed = FALSE
                   AND second.__subsumed = FALSE
                   AND first.c1 IS DISTINCT FROM second.c1
                   AND (first.__generation >= CAST('0' AS UBIGINT)
                       OR second.__generation >= CAST('0' AS UBIGINT))
             )
             SELECT bindings.*,
                    row_number() OVER (ORDER BY c0, c1, c2, c3, c4)
                        AS __match_ordinal
             FROM bindings;

-- SQL statement 001713 via duckdb_extract_statements
SELECT count(*) FROM egglog_path_stage_3_0;

-- SQL statement 001714 via duckdb_extract_statements
CREATE TEMP TABLE egglog_path_queue_3_0 (
                         __wave UBIGINT NOT NULL,
                         __event_ordinal UBIGINT NOT NULL,
                         c0 UBIGINT NOT NULL,
                         c1 UBIGINT NOT NULL,
                         c2 UBIGINT NOT NULL
                     );

-- SQL statement 001715 via duckdb_extract_statements
CREATE TEMP TABLE egglog_path_head_proof_3_0 AS
                     SELECT c2 AS c0,
                            c4 AS c1,
                            CAST('165' AS UBIGINT) + __match_ordinal - 1 AS c2,
                            CAST(TRUE AS BOOLEAN) AS c3,
                            __match_ordinal AS __ordinal
                     FROM egglog_path_stage_3_0;

-- SQL statement 001716 via duckdb_extract_statements
SELECT EXISTS (SELECT 1 FROM egglog_path_head_proof_3_0 GROUP BY c0, c1, c2 HAVING count(DISTINCT c3) > 1) OR EXISTS (
             SELECT 1
             FROM egglog_path_head_proof_3_0 AS candidate
             JOIN egglog_function_14 AS existing ON existing.c0 IS NOT DISTINCT FROM candidate.c0 AND existing.c1 IS NOT DISTINCT FROM candidate.c1 AND existing.c2 IS NOT DISTINCT FROM candidate.c2
             WHERE candidate.c3 IS DISTINCT FROM existing.c3
         );

-- SQL statement 001717 via duckdb_extract_statements
INSERT INTO egglog_function_14 (c0, c1, c2, c3, __generation, __subsumed)
         SELECT ranked.c0, ranked.c1, ranked.c2, ranked.c3, CAST('4' AS UBIGINT), FALSE
         FROM (
             SELECT staged.*,
                    row_number() OVER (PARTITION BY staged.c0, staged.c1, staged.c2 ORDER BY staged.__ordinal) AS __key_rank
             FROM egglog_path_head_proof_3_0 AS staged
         ) AS ranked
         WHERE ranked.__key_rank = 1 AND NOT EXISTS (SELECT 1 FROM egglog_function_14 AS existing WHERE existing.c0 IS NOT DISTINCT FROM ranked.c0 AND existing.c1 IS NOT DISTINCT FROM ranked.c1 AND existing.c2 IS NOT DISTINCT FROM ranked.c2);

-- SQL statement 001718 via duckdb_extract_statements
INSERT INTO egglog_path_queue_3_0 (__wave, __event_ordinal, c0, c1, c2)
                     SELECT CAST('0' AS UBIGINT),
                            CAST('0' AS UBIGINT) + __match_ordinal,
                            c0,
                            c3,
                            CAST('165' AS UBIGINT) + __match_ordinal - 1
                     FROM egglog_path_stage_3_0
                     ORDER BY __match_ordinal;

-- SQL statement 001719 via duckdb_extract_statements
SELECT EXISTS (
                         SELECT 1 FROM egglog_function_22 GROUP BY c0 HAVING count(*) > 1
                     ) OR EXISTS (
                         SELECT 1 FROM egglog_function_22 WHERE __subsumed
                     );

-- SQL statement 001720 via duckdb_extract_statements
SELECT count(*) FROM egglog_path_queue_3_0 WHERE __wave = CAST('0' AS UBIGINT);

