                     SELECT selected.__wave,
                            selected.__event_ordinal,
                            selected.c0 AS new_c0, selected.c1 AS new_c1, selected.c2 AS new_c2, selected.c3 AS new_c3,
                            existing.c0 AS old_c0, existing.c1 AS old_c1, existing.c2 AS old_c2, existing.c3 AS old_c3,
                            existing.__generation AS old_generation,
                            existing.__subsumed AS old_subsumed
