CREATE TEMP TABLE egglog_path_stage_9_0 AS
             WITH bindings AS (
                 SELECT DISTINCT
                        first.c0 AS c0,
                        first.c1 AS c1,
                        first.c2 AS c2,
                        second.c1 AS c3,
                        second.c2 AS c4
                 FROM egglog_function_22 AS first
                 JOIN egglog_function_22 AS second
                   ON first.c1 IS NOT DISTINCT FROM second.c0
                 WHERE first.__subsumed = FALSE
                   AND second.__subsumed = FALSE
                   AND first.c1 IS DISTINCT FROM second.c1
                   AND (first.__generation >= CAST('5' AS UBIGINT)
                       OR second.__generation >= CAST('5' AS UBIGINT))
             )
             SELECT bindings.*,
                    row_number() OVER (ORDER BY c0, c1, c2, c3, c4)
                        AS __match_ordinal
             FROM bindings;

