-- SQL statement 003886 via duckdb_extract_statements
CREATE TEMP TABLE egglog_scalar_collision_14_0 AS
                     SELECT outcome.*,
                            CASE WHEN old_c2 < new_c2
                                 THEN old_c2 ELSE new_c2 END AS min_identity,
                            CASE WHEN old_c2 > new_c2
                                 THEN old_c2 ELSE new_c2 END AS max_identity,
